1	package cometfit;
2	
3	import java.time.Duration;
4	import java.time.Instant;
5	import java.time.LocalDate;
6	
7	import org.slf4j.Logger;
8	import org.slf4j.LoggerFactory;
9	import org.springframework.boot.ApplicationArguments;
10	import org.springframework.boot.ApplicationRunner;
11	import org.springframework.boot.autoconfigure.condition.ConditionalOnProperty;
12	import org.springframework.stereotype.Component;
13	import org.springframework.transaction.annotation.Transactional;
14	
15	import cometfit.domain.ActivityRecord;
16	import cometfit.domain.ActivityRecordRepository;
17	import cometfit.domain.ConsentSettings;
18	import cometfit.domain.ConsentSettingsRepository;
19	import cometfit.domain.DeviceLink;
20	import cometfit.domain.DeviceLinkRepository;
21	import cometfit.domain.Friendship;
22	import cometfit.domain.FriendshipRepository;
23	import cometfit.domain.MealEntry;
24	import cometfit.domain.MealEntryRepository;
25	import cometfit.domain.MealSource;
26	import cometfit.domain.PointAccount;
27	import cometfit.domain.PointAccountRepository;
28	import cometfit.domain.PointTransaction;
29	import cometfit.domain.PointTransactionRepository;
30	import cometfit.domain.RecVisit;
31	import cometfit.domain.RecVisitRepository;
32	import cometfit.domain.SmartDevice;
33	import cometfit.domain.SmartDeviceRepository;
34	import cometfit.domain.WaterEntry;
35	import cometfit.domain.WaterEntryRepository;
36	import cometfit.security.AccountService;
37	import cometfit.security.Permissions;
38	import cometfit.security.UserRepository;
39	import cometfit.services.Clock;
40	import cometfit.services.PointsService;
41	
42	/**
43	 * Demo accounts for the recorded demo (A-14). Disabled with COMETFIT_SEED_DEMO=false.
44	 * Fixed TOTP secrets so the presenter can generate codes with app/tools/totp.mjs or any authenticator app.
45	 * Actors: Developer (UC-4), Student / User / Friend (UC-1..UC-3).
46	 *
47	 * TD-2 (stage 2): the demo students alice and bob start with all data sharing turned on (calories, water, steps,
48	 * UREC visits) and have some activity history, so UC-3 (friends' progress and leaderboard) shows real numbers.
49	 * They are seeded as friends so the leaderboard lists both (A-40). Real new accounts keep sharing off (A-18).
50	 * History is written only when the two students are created, i.e. on a fresh database.
51	 */
52	@Component
53	@ConditionalOnProperty(name = "cometfit.seed-demo", havingValue = "true")
54	public class DemoDataSeeder implements ApplicationRunner {
55	    private static final Logger log = LoggerFactory.getLogger(DemoDataSeeder.class);
56	
57	    public static final String DEMO_PASSWORD = "CometFit123!";
58	    public static final String DEV_SECRET = "COMETFITDEVADMIN";
59	    public static final String ALICE_SECRET = "COMETFITALICE234";
60	    public static final String BOB_SECRET = "COMETFITBOBBY567";
61	    public static final String UREC_READER = "UREC-FRONT-1";
62	    /** Days of history before today (A-40). */
63	    public static final int HISTORY_DAYS = 6;
64	
65	    private final AccountService accounts;
66	    private final UserRepository users;
67	    private final Clock clock;
68	    private final ConsentSettingsRepository consents;
69	    private final FriendshipRepository friendships;
70	    private final MealEntryRepository meals;
71	    private final WaterEntryRepository water;
72	    private final SmartDeviceRepository devices;
73	    private final DeviceLinkRepository links;
74	    private final ActivityRecordRepository activity;
75	    private final RecVisitRepository visits;
76	    private final PointAccountRepository pointAccounts;
77	    private final PointTransactionRepository pointTx;
78	
79	    public DemoDataSeeder(AccountService accounts, UserRepository users, Clock clock,
80	                          ConsentSettingsRepository consents, FriendshipRepository friendships,
81	                          MealEntryRepository meals, WaterEntryRepository water, SmartDeviceRepository devices,
82	                          DeviceLinkRepository links, ActivityRecordRepository activity, RecVisitRepository visits,
83	                          PointAccountRepository pointAccounts, PointTransactionRepository pointTx) {
84	        this.accounts = accounts;
85	        this.users = users;
86	        this.clock = clock;
87	        this.consents = consents;
88	        this.friendships = friendships;
89	        this.meals = meals;
90	        this.water = water;
91	        this.devices = devices;
92	        this.links = links;
93	        this.activity = activity;
94	        this.visits = visits;
95	        this.pointAccounts = pointAccounts;
96	        this.pointTx = pointTx;
97	    }
98	
99	    /** One demo student's week (index 0 = 6 days ago, last = today). Values are fixed so every demo is the same. */
100	    private record Week(int[] mealCalories, int[] refillsOf500ml, int[] steps, boolean[] urecVisit) {}
101	
102	    private static final Week ALICE_WEEK = new Week(
103	            new int[]{1850, 2100, 1700, 1950, 2250, 1800, 1150},
104	            new int[]{4, 3, 5, 4, 2, 4, 2},
105	            new int[]{11200, 8400, 12650, 9800, 10400, 7600, 6300},
106	            new boolean[]{true, false, true, true, false, true, true});
107	    private static final Week BOB_WEEK = new Week(
108	            new int[]{2300, 2450, 2100, 2600, 2200, 2350, 900},
109	            new int[]{2, 3, 2, 4, 3, 2, 1},
110	            new int[]{6400, 10300, 5200, 8800, 11900, 7100, 4200},
111	            new boolean[]{false, true, false, false, true, false, false});
112	
113	    @Override
114	    @Transactional
115	    public void run(ApplicationArguments args) {
116	        if (!users.existsByUsernameIgnoreCase("dev")) {
117	            accounts.createDeveloper("dev", DEMO_PASSWORD, "dev@cometfit.local", "Dev Admin", "OPERATOR",
118	                    Permissions.DEVELOPER_DEFAULT, DEV_SECRET);
119	            log.info("Seeded demo developer 'dev' (TOTP secret {})", DEV_SECRET);
120	        }
121	        Long alice = null, bob = null;
122	        if (!users.existsByUsernameIgnoreCase("alice")) {
123	            alice = accounts.registerStudent("alice", DEMO_PASSWORD, "alice@cometfit.local", "Alice", ALICE_SECRET)
124	                    .user().getUserId();
125	            log.info("Seeded demo student 'alice' (TOTP secret {})", ALICE_SECRET);
126	        }
127	        if (!users.existsByUsernameIgnoreCase("bob")) {
128	            bob = accounts.registerStudent("bob", DEMO_PASSWORD, "bob@cometfit.local", "Bob", BOB_SECRET)
129	                    .user().getUserId();
130	            log.info("Seeded demo student 'bob' (TOTP secret {})", BOB_SECRET);
131	        }
132	        if (alice != null && bob != null) {
133	            seedDemoHistory(alice, bob);
134	        }
135	    }
136	
137	    /** TD-2: sharing on, friends, and a week of meals, water, steps, UREC visits and points. */
138	    private void seedDemoHistory(Long alice, Long bob) {
139	        for (Long id : new Long[]{alice, bob}) {
140	            ConsentSettings c = consents.findById(id).orElseGet(() -> new ConsentSettings(id));
141	            c.set(true, true, true, true);
142	            consents.save(c);
143	        }
144	        Instant now = Instant.now();
145	        LocalDate today = clock.today();
146	        friendships.save(new Friendship(alice, bob, clock.startOf(today.minusDays(HISTORY_DAYS + 1))));
147	        seedWeek(alice, "DEMO-WATCH-ALICE", ALICE_WEEK, today, now);
148	        seedWeek(bob, "DEMO-WATCH-BOB", BOB_WEEK, today, now);
149	        log.info("Seeded TD-2 demo data: alice and bob are friends, share all stats, {} days of history", HISTORY_DAYS + 1);
150	    }
151	
152	    private void seedWeek(Long student, String deviceId, Week w, LocalDate today, Instant now) {
153	        SmartDevice device = devices.save(new SmartDevice(deviceId, "watch", "simulated"));
154	        DeviceLink link = new DeviceLink(student, device);
155	        link.pair();
156	        links.save(link);
157	
158	        PointAccount account = pointAccounts.findById(student).orElseGet(() -> new PointAccount(student));
159	        for (int i = 0; i <= HISTORY_DAYS; i++) {
160	            LocalDate day = today.minusDays(HISTORY_DAYS - i);
161	            Instant start = clock.startOf(day);
162	
163	            int cal = w.mealCalories()[i];
164	            int[] split = {cal * 25 / 100, cal * 35 / 100, cal - cal * 25 / 100 - cal * 35 / 100};
165	            String[] names = {"Breakfast (demo)", "Lunch (demo)", "Dinner (demo)"};
166	            int[] hours = {8, 12, 18};
167	            for (int m = 0; m < 3; m++) {
168	                Instant t = at(start, hours[m], 0, now);
169	                if (t == null) continue;
170	                meals.save(new MealEntry(student, names[m], split[m], split[m] * 0.25 / 4, split[m] * 0.5 / 4,
171	                        split[m] * 0.25 / 9, MealSource.MANUAL, null, t));
172	            }
173	            for (int r = 0; r < w.refillsOf500ml()[i]; r++) {
174	                Instant t = at(start, 9 + r * 3, 0, now);
175	                if (t != null) water.save(new WaterEntry(student, 0.5, t));
176	            }
177	            int steps = w.steps()[i];
178	            int[] parts = {steps * 30 / 100, steps * 45 / 100, steps - steps * 30 / 100 - steps * 45 / 100};
179	            int[] syncHours = {10, 15, 20};
180	            int synced = 0;
181	            for (int p = 0; p < 3; p++) {
182	                Instant t = at(start, syncHours[p], 0, now);
183	                if (t == null) continue;
184	                activity.save(new ActivityRecord(student, device.getId(), parts[p], 70 + p * 12, t));
185	                synced += parts[p];
186	            }
187	            if (synced >= 10_000) award(account, student, PointsService.STEP_GOAL, at(start, 20, 1, now));
188	            if (w.urecVisit()[i]) {
189	                Instant t = at(start, 7, 30, now);
190	                if (t != null) {
191	                    visits.save(new RecVisit(student, UREC_READER, t));
192	                    award(account, student, PointsService.VISIT, t);
193	                }
194	            }
195	        }
196	        pointAccounts.save(account);
197	    }
198	
199	    private void award(PointAccount account, Long student, String reason, Instant t) {
200	        if (t == null) return;
201	        int amount = PointsService.pointsFor(reason);
202	        account.addPoints(amount);
203	        pointTx.save(new PointTransaction(student, amount, reason, t));
204	    }
205	
206	    /** start-of-day + h:m, or null when that time is still in the future (today's history stops at "now"). */
207	    private static Instant at(Instant startOfDay, int hour, int minute, Instant now) {
208	        Instant t = startOfDay.plus(Duration.ofHours(hour)).plus(Duration.ofMinutes(minute));
209	        return t.isAfter(now) ? null : t;
210	    }
211	}
