112	    @PostMapping(value = "/meals/photo", consumes = "multipart/form-data")
113	    public PhotoEstimate submitMealPhoto(@RequestHeader("Authorization") String token,
114	                                         @RequestParam("image") MultipartFile image) throws IOException {
115	        Student s = requireStudent(token, Permissions.NUTRITION);
116	        if (image.isEmpty()) throw ApiException.badRequest("Image is empty");
117	        String type = image.getContentType() == null ? "" : image.getContentType();
118	        if (!type.startsWith("image/")) throw ApiException.badRequest("File must be an image");
119	        List<FoodEstimate> items = aiFoodService.estimateMacros(image.getBytes());
120	        if (items.isEmpty()) throw ApiException.badRequest("No food recognised in the photo; enter it manually");
121	        String name = String.join(" + ", items.stream().map(FoodEstimate::foodName).toList());
122	        MealEntry draft = new MealEntry(s.getUserId(), name.length() > 120 ? name.substring(0, 120) : name,
123	                items.stream().mapToInt(FoodEstimate::calories).sum(),
124	                items.stream().mapToDouble(FoodEstimate::proteinG).sum(),
125	                items.stream().mapToDouble(FoodEstimate::carbsG).sum(),
126	                items.stream().mapToDouble(FoodEstimate::fatG).sum(),
127	                MealSource.PHOTO, null, Instant.now());
128	        return new PhotoEstimate(MealEntryView.of(draft), items,
129	                "Estimate only. Review and edit before saving. CometFit is a general wellness app.");
