152	    public SaveResult<MealEntryView> saveMealEntry(@RequestHeader("Authorization") String token,
153	                                                   @Valid @RequestBody MealEntryRequest r) {
154	        Student s = requireStudent(token, Permissions.NUTRITION);
155	        MealEntry e;
156	        if (r.source() == MealSource.DINING_MENU) {
157	            if (r.diningItemId() == null) throw ApiException.badRequest("diningItemId is required for DINING_MENU");
158	            DiningItem d = diningItems.findById(r.diningItemId())
159	                    .orElseThrow(() -> ApiException.notFound("Dining item not found"));
160	            e = new MealEntry(s.getUserId(), d.getName(), d.getCalories(), d.getProteinG(), d.getCarbsG(), d.getFatG(),
161	                    MealSource.DINING_MENU, d.getItemId(), Instant.now());
162	        } else {
163	            if (r.foodName() == null || r.foodName().isBlank()) throw ApiException.badRequest("foodName is required");
164	            if (r.calories() == null) throw ApiException.badRequest("calories is required");
165	            e = new MealEntry(s.getUserId(), r.foodName().trim(), r.calories(), nz(r.proteinG()), nz(r.carbsG()),
166	                    nz(r.fatG()), r.source(), null, Instant.now());
167	        }
168	        e = meals.save(e);
169	        return new SaveResult<>(MealEntryView.of(e), summaries.getDailySummary(s, clock.today()));
170	    }
