176	        LocalDate d = date == null ? clock.today() : date;
177	        return meals.findByStudentIdAndLoggedAtBetweenOrderByLoggedAtDesc(s.getUserId(), clock.startOf(d), clock.endOf(d))
178	                .stream().map(MealEntryView::of).toList();
