182	
183	    /**
184	     * saveWaterEntry(volumeMl) — SD-1 "log water (bottle size / refill) -> saveWaterEntry(volume) -> insert WaterEntry".
185	     * FR-6. The unit itself is team repo code LogWater.enter (liters or gallons, stored as liters): WaterLogService.
186	     */
187	    @PostMapping("/water")
188	    @ResponseStatus(HttpStatus.CREATED)
189	    public WaterSaveResult saveWaterEntry(@RequestHeader("Authorization") String token,
190	                                          @RequestBody WaterRequest r) {
191	        Student s = requireStudent(token, Permissions.NUTRITION);
192	        Double amount = r.amount();
193	        boolean isLiter = r.isLiter() == null || r.isLiter();
194	        if (amount == null && r.volumeMl() != null) {   // class-diagram form: milliliters -> liters
195	            amount = r.volumeMl() / 1000.0;
