72	
73	    /** FR-8 RTM: "open the food information tab and check different restaurants in UTD Dining for their nutritional values". */
74	    @Test
75	    void fr8_diningMenusListItemsWithMacrosPerLocation() throws Exception {
76	        Account a = newStudent("dine");
77	        JsonNode locations = GET("/api/nutrition/menu/locations", a, 200);
78	        assertThat(locations.size()).isGreaterThanOrEqualTo(2);
79	        for (JsonNode loc : locations) {
80	            JsonNode items = GET("/api/nutrition/menu?location=" + loc.asText(), a, 200);
81	            assertThat(items.size()).isPositive();
82	            for (JsonNode it : items) {
83	                assertThat(it.get("location").asText()).isEqualTo(loc.asText());
