content.content:
1	// UC-1 Track Nutrition & Hydration — SD-1, all three alt branches plus water:
2	//   [Photo entry]       take photo -> submitMealPhoto(image) -> show estimate for review -> confirm / edit
3	//   [Dining menu item]  browse dining menu -> getMenu(location) -> menu list -> select item   (FR-8)
4	//   [Manual entry]      enter food name and calories                                           (FR-2)
5	//   then saveMealEntry(entry); "log water (bottle size / refill)" -> saveWaterEntry(volume)    (FR-6)
6	//   Water input in liters or gallons: team repo code LogWater.java (stage 2).
7	// TD-4: layout of spec/05-ui-prototype/3-food-water.png — Today / Week / Month switch, Food and Water cards side by
8	// side (big number, "of goal", bar, "left", "+ Log food" / "+ <bottle> ml"), "Today's log" with F / W badges.
9	// TD-4 §3: water input stays liters/gallons (LogWater); totals are shown in ml as in the prototype. Week/Month: A-47.
10	import * as ImagePicker from 'expo-image-picker';
11	import React, { useState } from 'react';
12	import { Platform, ScrollView, Text, useWindowDimensions, View } from 'react-native';
13	import { api, ApiError } from '../api';
14	import {
15	  clockTime, lastNDates, leftOf, mergeTodayLog, parseMacro, parsePositiveAmount, parsePositiveInt, progress,
16	  refillVolume, toLiters,
17	} from '../logic';
18	import type { DailySummary, DiningItem, MealSource, PhotoEstimate } from '../types';
19	import {
20	  Banner, Button, Card, colors, Field, fmt, LetterBadge, MaintenanceNotice, ProgressBar, Row, s, Segmented,
21	} from '../ui';
22	import { useAsync } from '../useAsync';
23	
24	type Mode = 'MANUAL' | 'PHOTO' | 'DINING_MENU';
25	type Range = 'today' | 'week' | 'month';
26	
27	export default function LogScreen({ onChanged }: { onChanged: () => void }) {
28	  const [range, setRange] = useState<Range>('today');
29	  return (
30	    <ScrollView>
31	      <Segmented
32	        options={[{ id: 'today', label: 'Today' }, { id: 'week', label: 'Week' }, { id: 'month', label: 'Month' }]}
33	        value={range}
34	        onChange={setRange}
35	      />
36	      {range === 'today' ? <Today onChanged={onChanged} /> : <History days={range === 'week' ? 7 : 30} />}
37	    </ScrollView>
38	  );
39	}
40	
41	function Today({ onChanged }: { onChanged: () => void }) {
42	  const summaryQ = useAsync(() => api.summary(), []);
43	  const mealsQ = useAsync(() => api.meals(), []);
44	  const waterQ = useAsync(() => api.waterEntries(), []);
45	  const [panel, setPanel] = useState<'none' | 'food' | 'water'>('none');
46	  const [mode, setMode] = useState<Mode>('MANUAL');
47	  const [msg, setMsg] = useState<{ kind: 'good' | 'error'; text: string } | null>(null);
48	  const [busy, setBusy] = useState(false);
49	  const { width } = useWindowDimensions();
50	
51	  if (summaryQ.error?.isMaintenance) return <MaintenanceNotice name="Nutrition & Hydration" />;
52	
53	  function saved(summary: DailySummary, text: string) {
54	    summaryQ.setData(summary);
55	    mealsQ.reload();
56	    waterQ.reload();
57	    setMsg({ kind: 'good', text });
58	    onChanged();
59	  }
60	  function failed(e: unknown) {
61	    setMsg({ kind: 'error', text: (e as ApiError).message });
62	  }
63	  // FR-6 / Proposal §4 / A-8: one bottle refill, sent in liters (LogWater)
64	  async function refill(ml: number) {
65	    setBusy(true);
66	    try {
67	      const r = await api.saveWaterEntry(ml / 1000, true);
68	      saved(r.summary, r.message);
69	    } catch (e) {
70	      failed(e);
71	    } finally {
72	      setBusy(false);
73	    }
74	  }
75	
76	  const sum = summaryQ.data;
77	  const bottle = sum?.bottleSizeMl ?? 500;
78	  const log = mergeTodayLog(mealsQ.data ?? [], waterQ.data ?? []);
79	  const narrow = width < 360;
80	  return (
81	    <View>
82	      {msg ? <Banner kind={msg.kind}>{msg.text}</Banner> : null}
83	      {summaryQ.error && !summaryQ.error.isMaintenance ? <Banner kind="error">{summaryQ.error.message}</Banner> : null}
84	      {sum ? (
85	        <View style={{ flexDirection: narrow ? 'column' : 'row', gap: 12 }}>
86	          <View style={[s.card, { flex: 1 }]} testID="food-card">
87	            <Text style={st.cardLabel}>Food</Text>
88	            <Text style={st.big}>{fmt(sum.calories)}</Text>
89	            <Text style={s.muted}>cal</Text>
90	            <Text style={[s.muted, { marginTop: 10 }]}>of {fmt(sum.calorieGoal)} cal</Text>
91	            <ProgressBar value={progress(sum.calories, sum.calorieGoal)} color={colors.food} track={colors.foodBg} />
92	            <Text style={s.muted}>{fmt(leftOf(sum.calories, sum.calorieGoal))} cal left</Text>
93	            <View style={{ marginTop: 10 }}>
94	              <Button kind="food" label="+ Log food" onPress={() => setPanel(panel === 'food' ? 'none' : 'food')} testID="log-food" />
95	            </View>
96	          </View>
97	          <View style={[s.card, { flex: 1 }]} testID="water-card">
98	            <Text style={st.cardLabel}>Water</Text>
99	            <Text style={st.big}>{fmt(sum.waterMl)}</Text>
100	            <Text style={s.muted}>ml</Text>
101	            <Text style={[s.muted, { marginTop: 10 }]}>of {fmt(sum.waterGoalMl)} ml</Text>
102	            <ProgressBar value={progress(sum.waterMl, sum.waterGoalMl)} color={colors.water} track={colors.waterBg} />
103	            <Text style={s.muted}>{fmt(leftOf(sum.waterMl, sum.waterGoalMl))} ml left</Text>
104	            <View style={{ marginTop: 10 }}>
105	              <Button kind="water" label={`+ ${fmt(bottle)} ml`} onPress={() => refill(refillVolume(bottle, 1))} busy={busy} testID="refill" />
106	            </View>
107	            <Text style={[st.link, { color: colors.water }]} onPress={() => setPanel(panel === 'water' ? 'none' : 'water')} testID="more-water">
108	              {panel === 'water' ? 'Hide water options' : 'Other amount (L / gal)'}
109	            </Text>
110	          </View>
111	        </View>
112	      ) : null}
113	
114	      {/* FR-6 verification: low-intake message from the daily summary */}
115	      {(sum?.messages ?? []).map((m) => (
116	        <Banner key={m} kind={m.startsWith('Water goal reached') ? 'good' : 'warn'}>{m}</Banner>
117	      ))}
118	
119	      {panel === 'water' ? <WaterOptions bottle={bottle} onSaved={saved} onError={failed} /> : null}
120	
121	      {panel === 'food' ? (
122	        <Card title="Log food">
123	          <Row>
124	            {(['MANUAL', 'PHOTO', 'DINING_MENU'] as Mode[]).map((m) => (
125	              <View key={m} style={{ flex: 1, minWidth: 96 }}>
126	                <Button
127	                  kind={mode === m ? 'primary' : 'secondary'}
128	                  label={m === 'MANUAL' ? 'Manual' : m === 'PHOTO' ? 'Photo (AI)' : 'Dining menu'}
129	                  onPress={() => setMode(m)}
130	                />
131	              </View>
132	            ))}
133	          </Row>
134	          {mode === 'MANUAL' ? <ManualMeal source="MANUAL" onSaved={saved} onError={failed} /> : null}
135	          {mode === 'PHOTO' ? <PhotoMeal onSaved={saved} onError={failed} /> : null}
136	          {mode === 'DINING_MENU' ? <DiningMenu onSaved={saved} onError={failed} /> : null}
137	        </Card>
138	      ) : null}
139	
140	      <Card title="Today's log" right={`${log.length} ${log.length === 1 ? 'entry' : 'entries'}`}>
141	        {sum ? (
142	          <Text style={[s.small, { marginBottom: 4 }]}>
143	            Macros today: protein {sum.proteinG} g · carbs {sum.carbsG} g · fat {sum.fatG} g
144	          </Text>
145	        ) : null}
146	        {log.length === 0 ? <Text style={s.muted}>Nothing logged yet today.</Text> : null}
147	        {log.map((r, i) => (
148	          <View key={r.key} style={[st.logRow, i < log.length - 1 && st.logLine]}>
149	            <LetterBadge letter={r.kind === 'food' ? 'F' : 'W'} kind={r.kind} />
150	            <View style={{ flex: 1 }}>
151	              <Text style={st.logTitle}>{r.title}</Text>
152	              <Text style={s.small}>
153	                {clockTime(r.at)}
154	                {r.source ? ` · ${sourceLabel(r.source as MealSource)}` : ''}
155	                {r.detail ? ` · ${r.detail}` : ''}
156	              </Text>
157	            </View>
158	            {r.kind === 'food' ? (
159	              <Text style={st.logValue}>{fmt(r.calories ?? 0)} cal</Text>
160	            ) : (
161	              <Text style={[st.logValue, { color: colors.water }]}>{fmt(r.ml ?? 0)} ml</Text>
162	            )}
163	          </View>
164	        ))}
165	      </Card>
166	    </View>
167	  );
168	}
169	
170	// ---- Week / Month (A-47): one daily summary per day from the existing GET /api/nutrition/summary?date= ----------
171	function History({ days }: { days: number }) {
172	  const q = useAsync(() => Promise.all(lastNDates(days).map((d) => api.summary(d))), [days]);
173	  if (q.error?.isMaintenance) return <MaintenanceNotice name="Nutrition & Hydration" />;
174	  if (q.error) return <Banner kind="error">{q.error.message}</Banner>;
175	  if (!q.data) return <Text style={s.muted}>Loading…</Text>;
176	  const list = q.data;
177	  const cal = list.reduce((a, d) => a + d.calories, 0);
178	  const ml = list.reduce((a, d) => a + d.waterMl, 0);
179	  const waterDays = list.filter((d) => d.waterMl >= d.waterGoalMl).length;
180	  return (
181	    <View>
182	      <View style={{ flexDirection: 'row', gap: 12 }}>
183	        <View style={[s.card, { flex: 1 }]}>
184	          <Text style={st.cardLabel}>Food</Text>
185	          <Text style={st.big}>{fmt(cal / days)}</Text>
186	          <Text style={s.muted}>cal / day on average</Text>
187	          <Text style={[s.muted, { marginTop: 8 }]}>{fmt(cal)} cal in {days} days</Text>
188	        </View>
189	        <View style={[s.card, { flex: 1 }]}>
190	          <Text style={st.cardLabel}>Water</Text>
191	          <Text style={st.big}>{fmt(ml / days)}</Text>
192	          <Text style={s.muted}>ml / day on average</Text>
193	          <Text style={[s.muted, { marginTop: 8 }]}>Goal reached on {waterDays} of {days} days</Text>
194	        </View>
195	      </View>
196	      <Card title={days === 7 ? 'Last 7 days' : 'Last 30 days'}>
197	        {[...list].reverse().map((d, i) => (
198	          <View key={d.date} style={[st.logRow, i < list.length - 1 && st.logLine]}>
199	            <Text style={[st.logTitle, { flex: 1 }]}>
200	              {new Date(`${d.date}T12:00:00`).toLocaleDateString('en-US', { weekday: 'short', month: 'short', day: 'numeric' })}
201	            </Text>
202	            <Text style={[st.logValue, { width: 90, textAlign: 'right' }]}>{fmt(d.calories)} cal</Text>
203	            <Text style={[st.logValue, { width: 90, textAlign: 'right', color: colors.water }]}>{fmt(d.waterMl)} ml</Text>
204	          </View>
205	        ))}
206	      </Card>
207	    </View>
208	  );
209	}
