211	const st = {
212	  cardLabel: { fontSize: 15, fontWeight: '600' as const, color: colors.text, marginBottom: 6 },
213	  big: { fontSize: 30, fontWeight: '700' as const, color: colors.text },
214	  link: { fontSize: 13, marginTop: 8, textAlign: 'center' as const, textDecorationLine: 'underline' as const },
215	  logRow: { flexDirection: 'row' as const, alignItems: 'center' as const, paddingVertical: 10 },
216	  logLine: { borderBottomWidth: 1, borderBottomColor: colors.border },
217	  logTitle: { fontSize: 15, color: colors.heading, fontWeight: '500' as const },
218	  logValue: { fontSize: 15, fontWeight: '700' as const, color: colors.text },
219	};
220	
221	function sourceLabel(src: MealSource) {
222	  return src === 'PHOTO' ? 'Photo' : src === 'DINING_MENU' ? 'UTD Dining' : 'Manual';
223	}
224	
225	type SavedFn = (s: DailySummary, text: string) => void;
226	type ErrFn = (e: unknown) => void;
227	
228	// ---- FR-6 water -----------------------------------------------------------------------------------------------
229	// Team repo code LogWater.enter(userId, amount, isLiter): the student can enter liters or gallons; the server stores
230	// liters truncated to two decimals and answers "Added 1.13L to Jane Doe". Refill buttons = Proposal §4 bottle refills.
231	function WaterOptions({ bottle, onSaved, onError }: { bottle: number; onSaved: SavedFn; onError: ErrFn }) {
232	  const [custom, setCustom] = useState('');
233	  const [isLiter, setIsLiter] = useState(true);
234	  const [busy, setBusy] = useState(false);
235	
236	  async function log(amount: number, liter: boolean) {
237	    setBusy(true);
238	    try {
239	      const r = await api.saveWaterEntry(amount, liter);
240	      onSaved(r.summary, r.message);
241	      setCustom('');
242	    } catch (e) {
243	      onError(e);
244	    } finally {
245	      setBusy(false);
246	    }
247	  }
248	  const customAmount = parsePositiveAmount(custom);
249	  const preview = customAmount !== null ? toLiters(customAmount, isLiter) : null;
250	  return (
251	    <Card title="Log water">
252	      <Button kind="water" label={`+ ½ bottle (${refillVolume(bottle, 0.5)} ml)`} onPress={() => log(refillVolume(bottle, 0.5) / 1000, true)} disabled={busy} />
253	      <Row>
254	        <View style={{ flex: 2 }}>
255	          <Field label={`Other amount (${isLiter ? 'liters' : 'gallons'})`} value={custom} onChangeText={setCustom} keyboardType="decimal-pad" testID="water-amount" />
256	        </View>
257	        <View style={{ flex: 1 }}>
258	          <Button kind={isLiter ? 'primary' : 'secondary'} label="L" onPress={() => setIsLiter(true)} testID="unit-liter" />
259	        </View>
260	        <View style={{ flex: 1 }}>
261	          <Button kind={!isLiter ? 'primary' : 'secondary'} label="gal" onPress={() => setIsLiter(false)} testID="unit-gallon" />
262	        </View>
263	      </Row>
264	      <Button
265	        kind="water"
266	        label={preview !== null ? `Add ${preview} L` : 'Add'}
267	        onPress={() => customAmount !== null && log(customAmount, isLiter)}
268	        disabled={customAmount === null || busy}
269	        testID="water-add"
270	      />
271	      <Text style={s.muted}>Water is saved in liters (gallons are converted). Bottle size can be changed in Account → Daily goals & units.</Text>
272	    </Card>
273	  );
274	}
275	
276	// ---- [Manual entry] (also used to confirm / edit a photo estimate) ---------------------------------------------
277	function ManualMeal({
278	  source, initial, onSaved, onError, onDone,
279	}: {
280	  source: MealSource;
281	  initial?: { foodName: string; calories: number; proteinG: number; carbsG: number; fatG: number };
282	  onSaved: SavedFn;
283	  onError: ErrFn;
284	  onDone?: () => void;
285	}) {
286	  const [name, setName] = useState(initial?.foodName ?? '');
287	  const [cal, setCal] = useState(initial ? String(initial.calories) : '');
288	  const [p, setP] = useState(initial ? String(round1(initial.proteinG)) : '');
289	  const [c, setC] = useState(initial ? String(round1(initial.carbsG)) : '');
290	  const [f, setF] = useState(initial ? String(round1(initial.fatG)) : '');
291	  const [busy, setBusy] = useState(false);
292	
293	  const calories = cal.trim() === '0' ? 0 : parsePositiveInt(cal, 5000);
294	  const macros = [parseMacro(p), parseMacro(c), parseMacro(f)];
295	  const valid = name.trim().length > 0 && calories !== null && macros.every((x) => x !== null);
296	
297	  async function save() {
298	    setBusy(true);
299	    try {
300	      const r = await api.saveMealEntry({
301	        source, foodName: name.trim(), calories: calories!, proteinG: macros[0]!, carbsG: macros[1]!, fatG: macros[2]!,
302	      });
303	      onSaved(r.summary, `Saved "${r.saved.foodName}" (${r.saved.calories} kcal).`);
304	      setName(''); setCal(''); setP(''); setC(''); setF('');
305	      onDone?.();
306	    } catch (e) {
307	      onError(e);
308	    } finally {
309	      setBusy(false);
310	    }
311	  }
312	
313	  return (
314	    <View style={{ marginTop: 8 }}>
315	      <Field label="Food name" value={name} onChangeText={setName} testID="food-name" />
316	      <Field label="Calories (kcal)" value={cal} onChangeText={setCal} keyboardType="number-pad" testID="food-cal" />
317	      <Row>
318	        <View style={{ flex: 1 }}><Field label="Protein g" value={p} onChangeText={setP} keyboardType="decimal-pad" /></View>
319	        <View style={{ flex: 1 }}><Field label="Carbs g" value={c} onChangeText={setC} keyboardType="decimal-pad" /></View>
320	        <View style={{ flex: 1 }}><Field label="Fat g" value={f} onChangeText={setF} keyboardType="decimal-pad" /></View>
321	      </Row>
322	      <Button label={source === 'PHOTO' ? 'Confirm & save' : 'Save meal'} onPress={save} disabled={!valid} busy={busy} testID="save-meal" />
323	    </View>
324	  );
325	}
326	
327	function round1(n: number) {
328	  return Math.round(n * 10) / 10;
329	}
330	
331	// ---- [Photo entry] ---------------------------------------------------------------------------------------------
332	function PhotoMeal({ onSaved, onError }: { onSaved: SavedFn; onError: ErrFn }) {
333	  const [estimate, setEstimate] = useState<PhotoEstimate | null>(null);
334	  const [busy, setBusy] = useState(false);
335	
336	  async function pick(camera: boolean) {
337	    try {
338	      if (camera && Platform.OS !== 'web') {
339	        const perm = await ImagePicker.requestCameraPermissionsAsync();
340	        if (!perm.granted) throw new ApiError(0, 'PERMISSION', 'Camera permission is needed to photograph a meal');
341	      }
342	      const opts: ImagePicker.ImagePickerOptions = { mediaTypes: ['images'], quality: 0.6 };
343	      const res = camera && Platform.OS !== 'web' ? await ImagePicker.launchCameraAsync(opts) : await ImagePicker.launchImageLibraryAsync(opts);
344	      if (res.canceled || !res.assets?.length) return;
345	      const asset = res.assets[0];
346	      setBusy(true);
347	      const form = new FormData();
348	      const type = asset.mimeType ?? 'image/jpeg';
349	      if (Platform.OS === 'web') {
350	        const blob = await (await fetch(asset.uri)).blob();
351	        form.append('image', blob, asset.fileName ?? 'meal.jpg');
352	      } else {
353	        form.append('image', { uri: asset.uri, name: asset.fileName ?? 'meal.jpg', type } as unknown as Blob);
354	      }
355	      setEstimate(await api.submitMealPhoto(form));
356	    } catch (e) {
357	      onError(e);
358	    } finally {
359	      setBusy(false);
360	    }
361	  }
362	
363	  return (
364	    <View style={{ marginTop: 8 }}>
365	      <Text style={s.muted}>
366	        Take a photo of your meal and CometFit will estimate the calories and macros. You can edit the estimate before saving.
367	      </Text>
368	      <Row>
369	        <View style={{ flex: 1 }}>
370	          <Button label={Platform.OS === 'web' ? 'Choose meal photo' : 'Take photo'} onPress={() => pick(true)} busy={busy} />
371	        </View>
372	        {Platform.OS !== 'web' ? (
373	          <View style={{ flex: 1 }}>
374	            <Button kind="secondary" label="From gallery" onPress={() => pick(false)} disabled={busy} />
375	          </View>
376	        ) : null}
377	      </Row>
378	      {estimate ? (
379	        <View style={{ marginTop: 8 }}>
380	          <Banner kind="info">{estimate.notice}</Banner>
381	          {estimate.foodItems.map((f) => (
382	            <Text key={f.foodName} style={s.muted}>
383	              • {f.foodName}: {f.calories} kcal (confidence {Math.round(f.confidence * 100)}%)
384	            </Text>
385	          ))}
386	          <ManualMeal
387	            key={estimate.draft.foodName + estimate.draft.calories}
388	            source="PHOTO"
389	            initial={estimate.draft}
390	            onSaved={onSaved}
391	            onError={onError}
392	            onDone={() => setEstimate(null)}
393	          />
394	        </View>
395	      ) : null}
396	    </View>
397	  );
398	}
399	
400	// ---- [Dining menu item] — FR-8 ---------------------------------------------------------------------------------
401	function DiningMenu({ onSaved, onError }: { onSaved: SavedFn; onError: ErrFn }) {
402	  const locations = useAsync(() => api.menuLocations(), []);
403	  const [location, setLocation] = useState<string | null>(null);
404	  const [items, setItems] = useState<DiningItem[] | null>(null);
405	  const [busyId, setBusyId] = useState<number | null>(null);
406	
407	  async function open(loc: string) {
408	    setLocation(loc);
409	    setItems(null);
410	    try {
411	      setItems(await api.getMenu(loc));
412	    } catch (e) {
413	      onError(e);
414	    }
415	  }
416	  async function add(item: DiningItem) {
417	    setBusyId(item.itemId);
418	    try {
419	      const r = await api.saveMealEntry({ source: 'DINING_MENU', diningItemId: item.itemId });
420	      onSaved(r.summary, `Added "${item.name}" from ${item.location}.`);
421	    } catch (e) {
422	      onError(e);
423	    } finally {
424	      setBusyId(null);
425	    }
426	  }
427	
428	  return (
429	    <View style={{ marginTop: 8 }}>
430	      <Text style={s.muted}>Nutrition facts for UTD Dining locations.</Text>
431	      <Row>
432	        {(locations.data ?? []).map((l) => (
433	          <View key={l} style={{ flex: 1, minWidth: 120 }}>
434	            <Button kind={location === l ? 'primary' : 'secondary'} label={l} onPress={() => open(l)} />
435	          </View>
436	        ))}
437	      </Row>
438	      {location && !items ? <Text style={s.muted}>Loading menu…</Text> : null}
439	      {(items ?? []).map((it) => (
440	        <View key={it.itemId} style={[s.listItem, { flexDirection: 'row', alignItems: 'center' }]}>
441	          <View style={{ flex: 1 }}>
442	            <Text style={s.body}>{it.name}</Text>
443	            <Text style={s.muted}>
444	              {it.calories} kcal · Protein {it.proteinG} g · Carbs {it.carbsG} g · Fat {it.fatG} g
445	            </Text>
446	          </View>
447	          <View style={{ width: 90 }}>
448	            <Button kind="secondary" label="Add" onPress={() => add(it)} busy={busyId === it.itemId} />
449	          </View>
450	        </View>
451	      ))}
452	      <Text style={[s.muted, { marginTop: 6, color: colors.muted }]}>Menu data comes from UTD Dining (stubbed in this build).</Text>
453	    </View>
454	  );
455	}
