        for (JsonNode it : menu(a, "The Halal Shack")) assertThat(it.get("proteinG").isNull()).isTrue();
        JsonNode fruit = item(a, "Chick-fil-A", "Fruit Cup");         // only fat missing
        assertThat(fruit.get("fatG").isNull()).isTrue();
