        assertThat(s.get("fatG").asDouble()).isEqualTo(18.0);
        assertThat(s.get("mealCount").asInt()).isEqualTo(2);
        assertThat(s.get("mealsWithUnpublishedMacros").asInt()).isEqualTo(1);
    }

